#!/usr/bin/env bash
# Rebuild the same 101-case I/M/Sv/Svnapot cohort with the actual hart profile.
# Test sources and self-checking signatures are generated by ACT4 + Sail.
set -euo pipefail
script_dir=$(cd -- "$(dirname -- "$0")" && pwd)
workspace=$(cd -- "$script_dir/../../../.." && pwd)
output=$(realpath -m -- "${1:-$workspace/npc/rv64/build/chengyue64/act4-profile}")
arch="$workspace/am-kernels/arch-test"
python3 - "$arch" "$output" <<'PYPROFILE'
from pathlib import Path
import shutil,re,sys
arch,out=map(Path,sys.argv[1:])
cfg=out/"config"
shutil.copytree(arch/"config/npc-rv64-ooo-current-linux-gnu",cfg,dirs_exist_ok=True)
p=cfg/"test_config.yaml"
p.write_text(re.sub(r"^name: .*$","name: r64-rebuild",p.read_text(),flags=re.M))
p=cfg/"sail.json";s=p.read_text()
s,n=re.subn(r'("Svrsw60t59b":\s*\{\s*"supported":\s*)true',r'\1false',s)
if n!=1:raise SystemExit("missing known Sail capability setting")
p.write_text(s)
PYPROFILE
act_env="$arch/env"
export VIRTUAL_ENV="$act_env/act4-venv" GEM_HOME="$act_env/gems" GEM_PATH="$act_env/gems"
export BUNDLE_PATH="$act_env/gems/bundle" BUNDLE_USER_HOME="$act_env/gems/bundle-home"
export BUNDLE_APP_CONFIG="$act_env/gems/bundle-config"
export PATH="$act_env/act4-venv/bin:$act_env/gems/bin:$act_env/sail-riscv-0.12/bin:$act_env/xpack-riscv-none-elf-gcc-15.2.0-1/bin:/usr/local/bin:/usr/bin:/bin"
export NPC_ACT4_RUBY_DEV_ROOT="$act_env/ruby-dev-deb/extract"
export RUBYLIB="$act_env/ruby-dev-patch" RUBYOPT=-rnpc_act4_rbconfig_patch
make -C "$arch/src/riscv-arch-test" elfs CONFIG_FILES="$output/config/test_config.yaml" WORKDIR="$output/work" EXTENSIONS=I,M,Sv,Svnapot JOBS="${R64_ACT4_JOBS:-4}"
